import React, { useContext, useMemo } from 'react';
import { useIntl } from 'react-intl';

import { ArrowLeftIcon } from '@dynatrace/strato-icons';

import { Button } from '../../../../../../buttons/button/Button.js';
import { Flex } from '../../../../../../layouts-core/flex/Flex.js';
import { Grid } from '../../../../../../layouts-core/grid/Grid.js';
import { Tooltip } from '../../../../../../overlays/tooltip/Tooltip.js';
import { TextEllipsis } from '../../../../../../typography/TextEllipsis.js';
import { singleLineName } from '../../../../functions/single-line-name.js';
import { TooltipItem } from '../../../../types/tooltip.js';
import { COPY_TO_CLIPBOARD_MESSAGES } from '../../../copy-to-clipboard/copy-to-clipboard-messages.js';
import { CopyToClipboard } from '../../../copy-to-clipboard/CopyToClipboard.js';
import {
  StyledTooltipContainer,
  DEFAULT_TOOLTIP_MIN_WIDTH,
} from '../components/InteractiveChartTooltip.styles.js';
import { InteractiveTooltipContext } from '../context/InteractiveTooltipContext.js';
import { renderActionChildren } from '../functions/render-action-children.js';

const BUTTON_WIDTH = 36;

interface InteractiveChartTooltipActionsProps {
  actions?: (s: TooltipItem) => React.ReactElement | undefined;
  showBackButton?: boolean;
  nameFormatter?: (item: TooltipItem) => string;
  pointerEvents?: boolean;
}

export const SeriesBasedTooltipActions = (
  props: InteractiveChartTooltipActionsProps,
) => {
  const {
    actions,
    showBackButton = false,
    nameFormatter,
    pointerEvents,
  } = props;
  const { selectedItem, selectItem } = useContext(InteractiveTooltipContext);
  const intl = useIntl();

  const tooltipCopyMessage = useMemo(
    () => [
      intl.formatMessage(COPY_TO_CLIPBOARD_MESSAGES.copyActionName),
      intl.formatMessage(COPY_TO_CLIPBOARD_MESSAGES.actionCopied),
    ],
    [],
  );

  const templateColumns = showBackButton
    ? `${BUTTON_WIDTH}px 1fr ${BUTTON_WIDTH}px`
    : `1fr ${BUTTON_WIDTH}px`;

  if (!selectedItem) {
    return null;
  }
  const name =
    nameFormatter?.(selectedItem) ??
    singleLineName(selectedItem.name) ??
    selectedItem.id;

  return (
    <StyledTooltipContainer
      minWidth={DEFAULT_TOOLTIP_MIN_WIDTH}
      allowPointerEvents={pointerEvents}
    >
      <Flex gap={0} flexDirection="column">
        <Grid
          gridTemplateColumns={templateColumns}
          height={32}
          alignItems="center"
          paddingLeft={12}
          paddingRight={8}
        >
          {showBackButton && (
            <Button
              data-testid="actions-back-button"
              variant="default"
              onClick={(e) => selectItem(e, undefined)}
            >
              <Button.Prefix>{<ArrowLeftIcon />}</Button.Prefix>
            </Button>
          )}
          <Tooltip placement="top" text={name}>
            <TextEllipsis truncationMode="middle" aria-label="Series name">
              {name}
            </TextEllipsis>
          </Tooltip>
          <CopyToClipboard textToCopy={name} tooltipText={tooltipCopyMessage} />
        </Grid>
        {actions && renderActionChildren(actions(selectedItem))}
      </Flex>
    </StyledTooltipContainer>
  );
};

SeriesBasedTooltipActions['displayName'] = 'SeriesBasedTooltipActions';
